package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
 * an existing one — sharing the same postcode and a phonetically equal last name but a
 * different {@link IdentityKey} (see {@link PossibleDuplicate}). Such an owner is still
 * created; the matching owner's id is stored in {@code possibleDuplicateOf} so a later read
 * can flag it.
 *
 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected exact-identity duplicates, so
 * a match reaching here is a distinct owner admitted by its differing identity key. The
 * earliest-created (lowest id) matching owner is recorded, and no match leaves the field unset.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Integer matchId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner is not a duplicate to flag against
            }
            if (PossibleDuplicate.matches(existing, owner)) {
                Integer id = existing.getId();
                if (id != null && (matchId == null || id < matchId)) {
                    matchId = id;
                }
            }
        }
        owner.setPossibleDuplicateOf(matchId);
    }
}

===== PossibleDuplicate.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "possible duplicate": a softer match than the hard
 * {@link IdentityKey}. A new owner possibly duplicates an existing one when their last names
 * share the same {@link Soundex} code and they share the same postcode, yet their
 * {@link IdentityKey identity keys} differ — enough overlap to look like the same person
 * (typically a different telephone or email), yet distinct enough that
 * {@link EnsureUniqueIdentity} did not treat it as a hard duplicate.
 *
 * <p>The postcode must be present on both sides: two owners with no postcode do not share
 * one, so they are not flagged.
 *
 * @see FlagPossibleDuplicate records the matching owner at registration.
 */
final class PossibleDuplicate {

    private PossibleDuplicate() {
    }

    /** Whether {@code existing} is a possible duplicate of the new {@code candidate}. */
    static boolean matches(Owner existing, Owner candidate) {
        return samePostcode(existing, candidate)
                && sameSoundexLastName(existing, candidate)
                && differentIdentity(existing, candidate);
    }

    private static boolean sameSoundexLastName(Owner existing, Owner candidate) {
        return Soundex.of(existing.getLastName()).equals(Soundex.of(candidate.getLastName()));
    }

    private static boolean samePostcode(Owner existing, Owner candidate) {
        String postcode = candidate.getPostcode();
        return postcode != null && !postcode.isBlank() && postcode.equals(existing.getPostcode());
    }

    private static boolean differentIdentity(Owner existing, Owner candidate) {
        return !IdentityKey.of(existing).equals(IdentityKey.of(candidate));
    }
}

===== CapacityWarning.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * The single definition of the approaching-capacity warning: it is raised once a city already
 * holds at least {@link #THRESHOLD} owners but has not yet reached the hard limit enforced by
 * {@link EnsureCityHasCapacity} (compared case-insensitively, see {@link SameCity}). Surfaced on
 * every owner response so callers can spot a city nearing capacity before the create is rejected.
 */
final class CapacityWarning {

    /** Owners already in a city at or above which the approaching-capacity warning is raised. */
    static final int THRESHOLD = 40;

    private CapacityWarning() {
    }

    /** Whether {@code city} already holds between {@link #THRESHOLD} and one below the limit. */
    static boolean isRaised(String city, OwnerRepository ownerRepository) {
        int inCity = SameCity.count(ownerRepository.findAll(), city);
        return inCity >= THRESHOLD && inCity < EnsureCityHasCapacity.CAPACITY;
    }
}

===== EnsureCityHasCapacity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Create-owner step: rejects the request with a 409 when the new owner's city already holds
 * {@link #CAPACITY} or more owners (compared case-insensitively, see {@link SameCity}). Runs
 * after {@link ValidateOwnerFields} (so the city is present) and before {@link BuildOwner}.
 */
public class EnsureCityHasCapacity {

    /** The maximum number of owners a single city may hold. */
    static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        if (SameCity.count(ownerRepository.findAll(), request.getCity()) >= CAPACITY) {
            throw new CityAtCapacityException(request.getCity(), CAPACITY);
        }
    }
}

===== DisposableEmailDomains.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

/**
 * The single definition of the disposable email-domain blocklist: addresses whose domain is a
 * known throwaway provider are not accepted for an owner. Lookup only; a pure function of the
 * email address.
 */
public final class DisposableEmailDomains {

    private static final Set<String> BLOCKED =
            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    private DisposableEmailDomains() {
    }

    /** Whether {@code email}'s domain is on the disposable-domain blocklist. */
    public static boolean isBlocked(String email) {
        if (email == null) {
            return false;
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return false;
        }
        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
        return BLOCKED.contains(domain);
    }
}

