16	 * @see FlagPossibleDuplicate records the matching owner at registration.
17	 */
18	final class PossibleDuplicate {
19	
20	    private PossibleDuplicate() {
21	    }
22	
23	    /** Whether {@code existing} is a possible duplicate of the new {@code candidate}. */
24	    static boolean matches(Owner existing, Owner candidate) {
25	        return samePostcode(existing, candidate)
26	                && sameSoundexLastName(existing, candidate)
27	                && differentIdentity(existing, candidate);
28	    }
29	
30	    private static boolean sameSoundexLastName(Owner existing, Owner candidate) {
31	        return Soundex.of(existing.getLastName()).equals(Soundex.of(candidate.getLastName()));
32	    }
33	
34	    private static boolean samePostcode(Owner existing, Owner candidate) {
35	        String postcode = candidate.getPostcode();
36	        return postcode != null && !postcode.isBlank() && postcode.equals(existing.getPostcode());
37	    }
38	
39	    private static boolean differentIdentity(Owner existing, Owner candidate) {
40	        return !IdentityKey.of(existing).equals(IdentityKey.of(candidate));
41	    }
42	}
